/// EVT-14: the misconduct codes for the card's reason, as code and a few words.
enum Misconduct {
    static let known: Set<String> = ["fa", "ifab", "ussf"]

    /// The scheme a match's reasons are listed from: the one given when the watch knows it, else IFAB's.
    static func scheme(_ id: String?) -> String {
        if let id, known.contains(id) { return id }
        return "ifab"
    }

    /// A scheme's codes for a caution or (sendOff) a send-off, without the second caution's.
    static func codes(_ scheme: String, sendOff: Bool) -> [(code: String, meaning: String)] {
        switch Misconduct.scheme(scheme) {
        case "fa": return sendOff ? [("S1", "Serious foul play"), ("S2", "Violent conduct"), ("S3", "Spitting"), ("S4", "DOGSO by handball"), ("S5", "DOGSO by foul"), ("S6", "Abusive language")] : [("C1", "Unsporting behavior"), ("C2", "Dissent"), ("C3", "Persistent fouling"), ("C4", "Delaying restart"), ("C5", "Distance at restart"), ("C6", "Entered field"), ("C7", "Left field")]
        case "ifab": return sendOff ? [("SFP", "Serious foul play"), ("VC", "Violent conduct"), ("S", "Spitting or biting"), ("DOGSO-H", "DOGSO by handball"), ("DOGSO-F", "DOGSO by foul"), ("OFFINABUS", "Abusive language")] : [("UB", "Unsporting behavior"), ("DT", "Dissent"), ("PI", "Persistent fouling"), ("DR", "Delaying restart"), ("FRD", "Distance at restart"), ("E", "Entered field"), ("L", "Left field")]
        case "ussf": return sendOff ? [("SFP", "Serious foul play"), ("VC", "Violent conduct"), ("S", "Spitting"), ("DGH", "DOGSO by handball"), ("DGF", "DOGSO by foul"), ("AL", "Abusive language")] : [("UB", "Unsporting behavior"), ("DT", "Dissent"), ("PI", "Persistent fouling"), ("DR", "Delaying restart"), ("FRD", "Distance at restart"), ("ERL", "Entered or left field")]
        default: return []
        }
    }
}
